package movement

import (
	"encoding/json"
	"math"
	"os"
	"path/filepath"
	"testing"

	"lodestone/server/pkg/constants"
	"lodestone/server/pkg/proto"
)

// TestReplaysDashGoldens replays WP13's dodge/dash trajectories generated by
// the TS step (client/src/sim/golden/wp13.ts) through this step: positions
// within 1e-9 m and the discrete state (mode, stamina, dash, i-frames)
// exactly. Passing means a dodging player is where the client predicted.
func TestReplaysDashGoldens(t *testing.T) {
	dir := filepath.Join("..", "..", "..", "client", "src", "sim", "golden")
	for _, name := range []string{"movement_wp13_dash_flat.json", "movement_wp13_dash_plane.json"} {
		raw, err := os.ReadFile(filepath.Join(dir, name))
		if err != nil {
			t.Skipf("client goldens not available: %v", err)
		}
		var g struct {
			Dt     float64 `json:"dt"`
			Ground struct {
				Kind                 string
				Height, Base, Sx, Sz float64
			} `json:"ground"`
			Initial [11]float64   `json:"initial"`
			Frames  [][5]float64  `json:"frames"` // seq flags yawU16 pitchI16 castSlot
			States  [][11]float64 `json:"states"` // x y z vx vy vz airJumps mode stamina dash iframes
		}
		if err := json.Unmarshal(raw, &g); err != nil {
			t.Fatal(err)
		}
		var ground Ground = Flat{Y: g.Ground.Height}
		if g.Ground.Kind == "plane" {
			ground = plane{g.Ground.Base, g.Ground.Sx, g.Ground.Sz}
		}
		s := NewState(Vec3{g.Initial[0], g.Initial[1], g.Initial[2]})
		dashes, inv := 0, 0
		for i, f := range g.Frames {
			s = StepFrame(s, proto.InputFrame{Seq: uint32(f[0]), Flags: uint16(f[1]), Yaw: uint16(f[2]), Pitch: int16(f[3]), CastSlot: uint8(f[4])}, ground)
			w := g.States[i]
			got := [11]float64{s.Pos.X, s.Pos.Y, s.Pos.Z, s.Vel.X, s.Vel.Y, s.Vel.Z, float64(s.AirJumps), float64(s.Mode), float64(s.Stamina), float64(s.Dash), float64(s.IFrames)}
			for k := range got {
				tol := 1e-9
				if k >= 6 {
					tol = 0
				}
				if math.Abs(got[k]-w[k]) > tol {
					t.Fatalf("%s frame %d field %d: go %v vs ts %v", name, i, k, got[k], w[k])
				}
			}
			if s.Dash > 0 {
				dashes++
			}
			if Invulnerable(s) {
				inv++
			}
		}
		if dashes == 0 || inv == 0 {
			t.Fatalf("%s: golden never dashed", name)
		}
	}
}

// TestDashValidationBounds: the zone's speed and rise bounds accept every
// dash variant (a legit dash must never snap the player back).
func TestDashValidationBounds(t *testing.T) {
	for v := 0; v <= 15; v++ {
		d := Dash(v)
		if d == nil {
			continue
		}
		s := NewState(Vec3{100, 0, 100})
		next := StepFrame(s, proto.InputFrame{Flags: proto.InputFlagDodge | proto.InputFlagForward, CastSlot: uint8(v)}, Flat{})
		if HorizontalSpeed(next) > MaxHorizontalSpeed(s, next) {
			t.Errorf("variant %d: speed %v over bound %v", v, HorizontalSpeed(next), MaxHorizontalSpeed(s, next))
		}
		if next.Vel.Y > max(constants.JumpForce, MaxDashLift)+1e-9 {
			t.Errorf("variant %d: lift %v over MaxDashLift", v, next.Vel.Y)
		}
	}
}
